import { apiAsClinic, createPersonApi, expect, test, uid } from '../support/app';

// Every screen that loads its data opens without a script error and without an error notice.
// (They share one loading/error helper: this catches a screen that stopped loading.)
const ROUTES = [
  '/pos/cobros',
  '/pos/caja',
  '/pos/inventario',
  '/pos/facturacion',
  '/pos/cuentas',
  '/pos/reportes',
  '/pos/servicios',
  '/equipo',
  '/arco-solicitudes',
  '/en-proceso',
  '/pacientes',
  '/agenda/espera',
  '/ajustes?s=seguridad',
  '/ajustes?s=cumplimiento',
  '/ajustes?s=crecimiento',
  '/ajustes?s=agenda',
  '/ajustes?s=terminal',
  '/ajustes?s=perfil',
  '/indicadores'
];

for (const route of ROUTES) {
  test(`la pantalla ${route} carga sin errores`, async ({ page }) => {
    const errors: string[] = [];
    page.on('pageerror', (e) => errors.push(e.message));
    await page.goto(route);
    await page.waitForLoadState('networkidle');
    await expect(page.locator('main, [role=main], body').first()).toBeVisible();
    await expect(page.locator('[role=alert]:visible')).toHaveCount(0);
    expect(errors).toEqual([]);
  });
}

test('el expediente de un paciente abre todas sus pestañas sin errores', async ({ page }) => {
  const api = await apiAsClinic();
  const id = await createPersonApi(api, `Pantalla${uid()}`);
  await api.dispose();
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto(`/pacientes/${id}`);
  await page.waitForLoadState('networkidle');
  const tabs = page.getByRole('tab');
  const n = await tabs.count();
  expect(n).toBeGreaterThan(2);
  for (let i = 0; i < n; i++) {
    await tabs.nth(i).click();
    await page.waitForLoadState('networkidle');
    await expect(page.locator('[role=alert]:visible')).toHaveCount(0);
  }
  expect(errors).toEqual([]);
});

test('Ajustes: cada bloque guarda lo suyo con un botón que acompaña el scroll', async ({ page }) => {
  await page.goto('/ajustes?s=negocio');
  await page.waitForLoadState('networkidle');
  const guardar = page.getByRole('button', { name: 'Guardar datos' });
  await expect(guardar).toBeVisible();
  await page.mouse.wheel(0, 300);
  await expect(guardar).toBeInViewport();
  await page.getByLabel(/^Teléfono/).first().fill('5512345678');
  await guardar.click();
  await expect(page.getByText('Datos guardados')).toBeVisible();
  await expect(page.getByText('Horario guardado')).toHaveCount(0);
});

test('al subir la foto de un especialista se elige qué parte mostrar', async ({ page }) => {
  await page.goto('/ajustes?s=perfil');
  await page.waitForLoadState('networkidle');
  // a small gradient PNG: the window only needs a readable picture
  const png = Buffer.from('', 'base64');
  await page.locator('input[type=file]').last().setInputFiles({ name: 'foto.png', mimeType: 'image/png', buffer: png });
  await expect(page.getByRole('heading', { name: 'Elige qué parte mostrar' })).toBeVisible();
  await expect(page.getByLabel('Zoom')).toBeVisible();
  await page.getByRole('button', { name: 'Usar esta parte' }).click();
  await expect(page.getByText('Foto guardada')).toBeVisible();
});
